import fsp from "node:fs/promises";
import { isAbsolute, relative, resolve } from "pathe";
import type { Nitro } from "nitro/types";

export async function prepare(
  nitro: Nitro,
  opts: {
    /** Public asset dirs regenerated by the build, which are safe to clean. */
    generatedAssetDirs?: string[];
  } = {}
) {
  if (nitro.options.builder === false) {
    const { assertUnbundledSupport } = await import("./unbundled/build.ts");
    assertUnbundledSupport(nitro);
  }
  const dirsToClean = [
    nitro.options.output.dir,
    ...(!nitro.options.noPublicDir ? [nitro.options.output.publicDir] : []),
    ...(!nitro.options.static ? [nitro.options.output.serverDir] : []),
  ];

  const generatedAssetDirs = new Set(opts.generatedAssetDirs?.map((dir) => resolve(dir)));
  for (const asset of nitro.options.publicAssets) {
    const sourceDir = resolve(asset.dir);
    if (generatedAssetDirs.has(sourceDir)) {
      continue;
    }
    const actualSourceDir = await realpathOrUndefined(sourceDir);
    if (!actualSourceDir) {
      continue;
    }
    for (const outputDir of dirsToClean) {
      const actualOutputDir = (await realpathOrUndefined(outputDir)) || resolve(outputDir);
      if (isInside(actualOutputDir, actualSourceDir)) {
        throw new Error(
          `Cannot prepare output directory ${outputDir}: publicAssets source ${asset.dir} is inside it and would be deleted.`
        );
      }
    }
  }

  for (const dir of dirsToClean) {
    await prepareDir(dir);
  }
}

async function prepareDir(dir: string) {
  await fsp.rm(dir, { recursive: true, force: true });
  await fsp.mkdir(dir, { recursive: true });
}

async function realpathOrUndefined(path: string) {
  return fsp.realpath(path).catch((error: NodeJS.ErrnoException) => {
    if (error.code === "ENOENT") {
      return undefined;
    }
    throw error;
  });
}

function isInside(parent: string, child: string) {
  const path = relative(parent, child);
  return !path || (path !== ".." && !path.startsWith("../") && !isAbsolute(path));
}
